C=[]
def add(cat,label,msg,ctx,rationale,tags,missing=False,amounts=None):
    n=sum(c['category']==cat for c in C)+1
    instruction,criteria=POL[cat]
    if amounts is not None:
        criteria={k:f'{v} Euro' for k,v in zip(('betrag_a','betrag_b','betrag_c','betrag_d'),amounts)}
        criteria['daten_fehlen']='Eine erforderliche Rechengröße fehlt'
    C.append({'id':f'de_clean_{cat}_{n:03d}','category':cat,'language':'de','schema_language':'de','split':'german_clean_primary','input':f'Kundennachricht:\n{msg.strip()}\n\nAktenauszug / Arbeitskontext:\n{ctx.strip()}', 'questions':{'decision':{'type':'choice','instructions':BASE+instruction,'criteria':criteria}},'expected':{'decision':label},'gold_rationale':rationale,'tags':tags.split(','),'information_status':'missing_or_unresolved' if missing else 'sufficient','synthetic':True})
